```java
package com.android.tools.lint.checks;

import static com.android.SdkConstants.ANDROID_URI;
import static com.android.SdkConstants.ATTR_NAME;
import static com.android.SdkConstants.TAG_SERVICE;

import com.android.annotations.NonNull;
import com.android.annotations.Nullable;
import com.android.tools.lint.client.api.JavaEvaluator;
import com.android.tools.lint.detector.api.Category;
import com.android.tools.lint.detector.api.Detector;
import com.android.tools.lint.detector.api.Implementation;
import com.android.tools.lint.detector.api.Issue;
import com.android.tools.lint.detector.api.Scope;
import com.android.tools.lint.detector.api.Severity;
import com.android.tools.lint.detector.api.XmlContext;
import com.google.common.collect.ImmutableList;
import com.intellij.psi.PsiClass;

import org.w3c.dom.Element;
import org.w3c.dom.Node;
import org.w3c.dom.NodeList;

import java.util.Collection;
import java.util.Collections;

public class AndroidAutoDetector extends Detector implements XmlScanner {
    public static final Issue ISSUE = Issue.create(
            "MissingMediaBrowserServiceIntentFilter",
            "Missing MediaBrowserService intent-filter",
            "An Automotive Media App requires an exported service that extends " +
            "`android.service.media.MediaBrowserService` with an `<intent-filter>` for the " +
            "action `android.media.browse.MediaBrowserService`.",
            Category.CORRECTNESS,
            6,
            Severity.ERROR,
            new Implementation(AndroidAutoDetector.class, Scope.MANIFEST_SCOPE));

    private static final String MEDIA_BROWSER_SERVICE = "android.service.media.MediaBrowserService";
    private static final String MEDIA_BROWSER_SERVICE_ACTION = "android.media.browse.MediaBrowserService";

    @Override
    public Collection<String> getApplicableElements() {
        return Collections.singletonList(TAG_SERVICE);
    }

    @Override
    public void visitElement(@NonNull XmlContext context, @NonNull Element element) {
        String name = element.getAttributeNS(ANDROID_URI, ATTR_NAME);
        if (name == null || name.isEmpty()) {
            return;
        }

        String fqcn = getServiceFqcn(context, name);
        JavaEvaluator evaluator = context.getEvaluator();
        PsiClass psiClass = evaluator.findClass(fqcn);
        if (psiClass == null) {
            // Could be a library class or the manifest uses a shorthand we cannot resolve;
            // fall back to a name check to avoid missing obvious cases.
            if (!fqcn.equals(MEDIA_BROWSER_SERVICE) && !name.endsWith("MediaBrowserService")) {
                return;
            }
        } else if (!evaluator.extendsClass(psiClass, MEDIA_BROWSER_SERVICE, false)) {
            return;
        }

        if (!hasMediaBrowserServiceAction(element)) {
            context.report(ISSUE, element, context.getLocation(element),
                    "MediaBrowserService is missing an intent-filter for action "
                            + "`android.media.browse.MediaBrowserService`");
        }
    }

    private static boolean hasMediaBrowserServiceAction(@NonNull Element service) {
        NodeList children = service.getChildNodes();
        for (int i = 0; i < children.getLength(); i++) {
            Node child = children.item(i);
            if (child.getNodeType() != Node.ELEMENT_NODE) {
                continue;
            }
            Element intentFilter = (Element) child;
            if (!"intent-filter".equals(intentFilter.getLocalName())) {
                continue;
            }
            NodeList actions = intentFilter.getElementsByTagName("action");
            for (int j = 0; j < actions.getLength(); j++) {
                Element action = (Element) actions.item(j);
                String actionName = action.getAttributeNS(ANDROID_URI, ATTR_NAME);
                if (MEDIA_BROWSER_SERVICE_ACTION.equals(actionName)) {
                    return true;
                }
            }
        }
        return false;
    }

    @NonNull
    private static String getServiceFqcn(@NonNull XmlContext context, @NonNull String name) {
        if (name.startsWith(".")) {
            return context.getMainProject().getPackage() + name;
        }
        if (name.indexOf('.') != -1) {
            return name;
        }
        return context.getMainProject().getPackage() + "." + name;
    }
}
```

