private static String getFqcn(XmlContext context, String name) {
    String pkg = context.getProject().getPackage();
    if (pkg == null || pkg.isEmpty()) {
        return name;
    }
    if (name.startsWith(".")) {
        return pkg + name;
    }
    if (name.indexOf('.') >= 0) {
        return name;
    }
    return pkg + "." + name;
}
```

